(* [comment removed for export] *)
Record drv_layout (L : heap_layout) (sp0 : word) : Prop := DRV_LAYOUT {
  dl_segs : hl_segs L = RSEGS;
  dl_malloc : hl_malloc L = 0x9dddc;
  dl_free : hl_free L = 0x9dc9c;
  dl_tp : hl_tp L = 0xcb040;
  dl_img_lo : hl_img_lo L = 0x10000;
  dl_img_hi : hl_img_hi L = 0xec000;
  dl_static : forall a, hl_alloc_static L a -> 0xeb448 <= a < 0xeb7f0;
  dl_ro : forall a, hl_alloc_ro L a -> (0x10000 <= a < 0xb9000) \/ (0xeb2b0 <= a < 0xeb2b8) \/ (0xeb2d0 <= a < 0xeb448) \/ (0xeb7f0 <= a < 0xeb7f8) \/ (0xebc34 <= a < 0xebc38) \/ bv_unsigned sp0 <= a;      (* [comment removed for export] *)
  dl_errno : hl_errno L = 0xcaf9c;
  dl_sptop : hl_sptop L = bv_unsigned sp0;
  dl_stack : 0 <= hl_stack L <= 16384;
  dl_k : 0 <= hl_k_per_malloc L;
  dl_b : 0 <= hl_b_overhead L
}.

Section FPX_1. Context {fx : PropExec.FPState}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable scfg : SpuriousCfg.
Section DrvLayout.
  Variable L : heap_layout.
  Variable HI : heap_iface.
  Hypothesis HIok : heap_iface_ok L scfg HI.
  Variable sp0 : word.
  Hypothesis Hsp : (0x7fff80000000 <= bv_unsigned sp0 <= 0x800000000000)%Z.
  Hypothesis Hal : bv_unsigned sp0 mod 16 = 0.
  Hypothesis DL : drv_layout L sp0.

  (* [comment removed for export] *)
  Lemma wseg_5d3cc : wseg_ok RSEGS (Z_to_bv 64 0xb2000) 28672 = true.
