  (* [comment removed for export] *)
  Lemma kn_blk_ok : forall vals ebs M' v n A,
    let E := Env (vals_ev vals) ebs in
    vals_ev vals v = Z_to_bv 64 A -> vals_ev vals 0 = sp0 ->
    block_range L A n -> defined M' A n ->
    know_ok RSEGS E M' (kn_blk v n).
Proof.
